<?php
declare(strict_types=1);
require_once __DIR__ . '/_helper.php';
use Illuminate\Database\Capsule\Manager as Capsule;

$id_entitas = po_id_entitas();
$entitas = po_entitas($id_entitas);
$produk = po_produk_list($id_entitas);
$error = trim((string) ($_GET['error'] ?? ''));

if (!function_exists('po_template_has_ppn')) {
    function po_template_has_ppn(int $id_entitas, string $kode_jenis_transaksi): bool
    {
        try {
            return Capsule::table('tb_template_jurnal as t')
                ->join('tb_template_jurnal_detail as d', 'd.id_template_jurnal', '=', 't.id_template_jurnal')
                ->where('t.id_entitas', $id_entitas)
                ->where('t.kode_jenis_transaksi', $kode_jenis_transaksi)
                ->where('t.status_aktif', 1)
                ->where('d.sumber_nominal', 'rumus_nominal')
                ->where('d.rumus_nominal', 'ppn')
                ->exists();
        } catch (Throwable $e) { return false; }
    }
}
if (!function_exists('po_template_ppn_aktif')) {
    function po_template_ppn_aktif(int $id_entitas): bool
    {
        foreach (['FAKTUR_PENJUALAN_TUNAI','FAKTUR_PENJUALAN_TRANSFER','FAKTUR_PENJUALAN_KREDIT'] as $kode) {
            if (po_template_has_ppn($id_entitas, $kode)) return true;
        }
        return false;
    }
}
$ppn_template_aktif = po_template_ppn_aktif($id_entitas);
$ppn_persen = $ppn_template_aktif ? pajak_default_persen($id_entitas, 'PPN', 11.0) : 0;
$paymentSetting = po_payment_setting($id_entitas);
$bankName = trim((string) ($paymentSetting->nama_bank ?? ''));
$bankAccount = trim((string) ($paymentSetting->nomor_rekening ?? ''));
$bankHolder = trim((string) ($paymentSetting->atas_nama_rekening ?? ''));
$qrisMerchantName = trim((string) ($paymentSetting->qris_nama_merchant ?? $bankHolder));
$qrisManualImageUrl = po_public_file_url((string) ($paymentSetting->qris_image_path ?? ''));
$kategoriList = [];
foreach ($produk as $p) { $kategoriList[trim((string)($p->nama_kategori_produk ?? 'Produk')) ?: 'Produk'] = true; }
ksort($kategoriList);
?>
