<div class="modal-bg" id="checkoutModal"><div class="modal"><div class="modal-head"><div><h3>Checkout Pesanan</h3><div>Keranjang akan diganti menjadi form checkout.</div></div><button class="modal-close" type="button" onclick="closeCheckout()">×</button></div><div class="modal-body"><form method="post" enctype="multipart/form-data" action="<?= po_esc(po_url('simpan.php')) ?>" id="checkoutForm"><input type="hidden" name="id_entitas" value="<?= (int)$id_entitas ?>"><input type="hidden" name="cart_json" id="cartJson"><div class="checkout-grid"><div><div class="box"><h4>Barang dipesan</h4><div id="checkoutItems" class="cart-list"></div></div><div class="summary"><div class="sum-row"><span>Subtotal</span><strong id="modalSubtotal">Rp 0</strong></div><div class="sum-row"><span>PPN</span><strong id="modalPpn">Rp 0</strong></div><div class="sum-row total"><span>Total</span><strong id="modalTotal">Rp 0</strong></div></div></div><div><div class="box"><h4>Data pelanggan</h4><div class="form-grid"><div><label class="label">Nama *</label><input class="control" name="nama_pelanggan" required placeholder="Nama lengkap"></div><div><label class="label">No HP/WA *</label><input class="control" name="no_hp" required placeholder="08xxxxxxxxxx"></div><div><label class="label">Email</label><input class="control" type="email" name="email" placeholder="opsional"></div><div><label class="label">Tanggal kirim</label><input class="control" type="date" name="tanggal_kirim_rencana"></div><div class="full"><label class="label">Alamat *</label><textarea class="control" name="alamat" required rows="3" placeholder="Alamat pengiriman/ambil"></textarea></div><div class="full"><label class="label">Catatan</label><textarea class="control" name="catatan" rows="2" placeholder="Catatan tambahan"></textarea></div></div></div><div class="box" style="margin-top:14px"><h4>Metode pembayaran</h4><div class="payment-options"><label class="pay"><input type="radio" name="metode_pembayaran_online" value="cod" checked onchange="updatePaymentInstruction()"><span>COD</span><small>Bayar saat diterima</small></label><label class="pay"><input type="radio" name="metode_pembayaran_online" value="transfer" onchange="updatePaymentInstruction()"><span>Transfer</span><small>Upload bukti</small></label><label class="pay"><input type="radio" name="metode_pembayaran_online" value="qris" onchange="updatePaymentInstruction()"><span>QRIS</span><small>Manual</small></label></div><div class="pay-info" id="paymentInstruction"></div><div class="proof-box" id="checkoutProofBox"><strong>Upload bukti pembayaran</strong><p style="margin:6px 0;color:#64748b;font-size:13px">Untuk Transfer/QRIS, unggah screenshot bukti bayar di sini. Bukti juga bisa diupload ulang dari Cek Pesanan.</p><input class="control" type="file" name="file_bukti_checkout" accept="image/*,application/pdf"></div></div><div class="checkout-actions"><button class="btn btn-soft" type="button" onclick="closeCheckout()">Kembali</button><button class="btn btn-orange" type="submit">Kirim Pesanan</button></div></div></div></form></div></div></div>
<button class="btn btn-orange floating-chat" type="button" onclick="openGeneralChat()"><span class="ico-only">💬</span><span class="btn-label">Chat</span></button>
<div class="modal-bg" id="generalChatModal"><div class="modal chat-window"><div class="modal-head"><div><h3>Chat Admin</h3><div>Chat umum tanpa nomor pesanan</div></div><button class="modal-close" type="button" onclick="closeGeneralChat()">×</button></div><div class="chat-products"><?php foreach($produk->take(8) as $p): ?><button class="prod-chip" type="button" onclick="fillGeneralChat('Saya mau tanya produk <?= po_esc($p->nama_produk) ?>')">🍬 <?= po_esc($p->nama_produk) ?></button><?php endforeach; ?></div><div class="quick"><button type="button" onclick="fillGeneralChat('Apakah produk ini masih tersedia?')">Tanya stok</button><button type="button" onclick="fillGeneralChat('Apakah bisa pesan hari ini?')">Pesan hari ini</button><button type="button" onclick="fillGeneralChat('Berapa lama proses pesanannya?')">Lama proses</button></div><div class="chat-body" id="generalChatRows"><div class="empty">Isi nama dan no HP, lalu kirim pertanyaan.</div></div><form class="chat-form" id="generalChatForm"><textarea id="generalChatText" rows="1" placeholder="Ketik pesan seperti WhatsApp Business..." required></textarea><button class="btn btn-primary" type="submit">Kirim</button><input type="hidden" id="generalName" value=""><input type="hidden" id="generalPhone" value=""></form></div></div>
<div class="success-toast" id="toast">Produk masuk ke keranjang</div>
<script>
const PPN_TEMPLATE_AKTIF=<?= $ppn_template_aktif?'true':'false' ?>; const PPN_PERCENT=<?= json_encode((float)$ppn_persen) ?>; const ENTITAS_ID=<?= (int)$id_entitas ?>;
const PAYMENT_SETTING=<?= json_encode(['bank_name'=>$bankName,'bank_account'=>$bankAccount,'bank_holder'=>$bankHolder,'qris_merchant_name'=>$qrisMerchantName,'qris_manual_image_url'=>$qrisManualImageUrl],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES) ?>;
const cart=new Map(); let generalSession='';
function rupiah(v){v=Math.round(Number(v||0));return 'Rp '+v.toString().replace(/\B(?=(\d{3})+(?!\d))/g,'.')}function qty(v){v=Number(v||0);return Number.isInteger(v)?String(v):v.toFixed(2)}function esc(t){return String(t||'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}function toast(t){const el=document.getElementById('toast');el.textContent=t;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),1200)}
function addToCartFromCard(card){let p={};try{p=JSON.parse(card.dataset.product||'{}')}catch(e){}addToCart(p)}function addToCartFromButton(btn){let p={};try{p=JSON.parse(btn.dataset.product||'{}')}catch(e){}addToCart(p)}
function addToCart(p){const id=Number(p.id_produk||0); if(!id)return alert('Produk tidak valid.'); const stok=Number(p.stok||0); if(stok<=0)return alert('Stok produk tidak tersedia.'); const old=cart.get(id); const next=old?Number(old.qty)+1:1; if(next>stok)return alert('Qty melebihi stok tersedia.'); cart.set(id,{...p,id_produk:id,harga:Number(p.harga||0),stok:stok,qty:next}); renderCart(); toast('Produk masuk ke keranjang');}
function changeQty(id,d){const it=cart.get(Number(id)); if(!it)return; updateQty(id,Number(it.qty)+Number(d))}function updateQty(id,q){id=Number(id);q=Number(q||0);const it=cart.get(id);if(!it)return;if(q<=0){cart.delete(id)}else{if(q>Number(it.stok)){alert('Qty melebihi stok.');q=Number(it.stok)}it.qty=q;cart.set(id,it)}renderCart()}function removeItem(id){cart.delete(Number(id));renderCart()}function clearCart(){if(cart.size&&confirm('Kosongkan keranjang?')){cart.clear();renderCart()}}
function arr(){return Array.from(cart.values())}function summary(){const a=arr();const item=a.length;const q=a.reduce((s,i)=>s+Number(i.qty||0),0);const sub=a.reduce((s,i)=>s+Number(i.qty||0)*Number(i.harga||0),0);const ppn=PPN_TEMPLATE_AKTIF?Math.round(sub*Number(PPN_PERCENT||0)/100):0;return{item,q,sub,ppn,total:sub+ppn}}
function renderCart(){const s=summary();document.getElementById('headCartCount').textContent=s.item;document.getElementById('cartSub').textContent=s.item+' item dipilih';document.getElementById('summaryItem').textContent=s.item;document.getElementById('summaryQty').textContent=qty(s.q);document.getElementById('summarySubtotal').textContent=rupiah(s.sub);document.getElementById('summaryPpn').textContent=rupiah(s.ppn);document.getElementById('summaryTotal').textContent=rupiah(s.total);document.getElementById('modalSubtotal').textContent=rupiah(s.sub);document.getElementById('modalPpn').textContent=rupiah(s.ppn);document.getElementById('modalTotal').textContent=rupiah(s.total);document.getElementById('cartJson').value=JSON.stringify(arr());const html=arr().map(i=>`<div class="cart-item"><div><strong>${esc(i.nama_produk)}</strong><div style="color:#64748b;font-size:12px">${esc(i.kode_produk)} · ${rupiah(i.harga)}</div><div style="font-weight:900;color:#6d5dfc">${rupiah(Number(i.qty)*Number(i.harga))}</div></div><div class="qty-row"><button type="button" onclick="changeQty(${i.id_produk},-1)">−</button><input type="number" min="1" max="${i.stok}" value="${i.qty}" onchange="updateQty(${i.id_produk},this.value)"><button type="button" onclick="changeQty(${i.id_produk},1)">+</button><button type="button" onclick="removeItem(${i.id_produk})">×</button></div></div>`).join('')||'<div class="empty">Keranjang masih kosong.</div>';document.getElementById('cartList').innerHTML=html;document.getElementById('checkoutItems').innerHTML=html;updatePaymentInstruction()}
function openCart(){document.getElementById('cartModal').classList.add('show')}function closeCart(){document.getElementById('cartModal').classList.remove('show')}function openCheckout(){if(!cart.size)return alert('Keranjang masih kosong.');closeCart();renderCart();document.getElementById('checkoutModal').classList.add('show')}function closeCheckout(){document.getElementById('checkoutModal').classList.remove('show')}
function selectedPay(){return document.querySelector('input[name="metode_pembayaran_online"]:checked')?.value||'cod'}
function copyRekening(btn){
    const val=btn?.dataset?.copy||'';
    if(!val)return alert('Nomor rekening belum tersedia.');
    if(navigator.clipboard&&navigator.clipboard.writeText){
        navigator.clipboard.writeText(val).then(()=>{btn.textContent='Tersalin';setTimeout(()=>btn.textContent='Salin',1200)}).catch(()=>fallbackCopy(val,btn));
    }else{fallbackCopy(val,btn)}
}
function fallbackCopy(val,btn){
    const ta=document.createElement('textarea');ta.value=val;ta.style.position='fixed';ta.style.opacity='0';document.body.appendChild(ta);ta.focus();ta.select();
    try{document.execCommand('copy');btn.textContent='Tersalin';setTimeout(()=>btn.textContent='Salin',1200)}catch(e){alert('Silakan salin manual: '+val)}
    document.body.removeChild(ta);
}
function updatePaymentInstruction(){
    const box=document.getElementById('paymentInstruction');if(!box)return;
    const m=selectedPay(),s=summary(),total=rupiah(s.total);
    document.getElementById('checkoutProofBox').classList.toggle('show',m==='transfer'||m==='qris');
    const copyBtn=`<button type="button" class="copy-rek-btn" data-copy="${esc(PAYMENT_SETTING.bank_account||'')}" onclick="copyRekening(this)">Salin</button>`;
    if(m==='transfer'){
        box.innerHTML=`<strong>Transfer Bank</strong><div class="transfer-clean"><div class="pay-line"><span>Nama Bank</span><b>${esc(PAYMENT_SETTING.bank_name||'-')}</b></div><div class="pay-line"><span>Nama Nasabah</span><b>${esc(PAYMENT_SETTING.bank_holder||'-')}</b></div><div class="pay-line"><span>No Rekening</span><b class="rekening-copy"><span>${esc(PAYMENT_SETTING.bank_account||'-')}</span>${copyBtn}</b></div></div>`;
        return;
    }
    if(m==='qris'){
        const img=PAYMENT_SETTING.qris_manual_image_url||'';
        box.innerHTML=`<strong>QRIS Manual</strong><div class="qris-only">${img?`<img class="qris-img-large" src="${esc(img)}" alt="QRIS Manual">`:'<div class="empty">Gambar QRIS manual belum diupload di Mapping Akun.</div>'}</div>`;
        return;
    }
    box.innerHTML=`<strong>Bayar di Tempat</strong><div class="pay-line"><span>Total</span><b>${total}</b></div><p style="color:#64748b;margin-bottom:0">Bayar saat pesanan diterima/diambil.</p>`
}
function applyFilterSort(){const q=(document.getElementById('searchProduk').value||'').toLowerCase();const kat=document.getElementById('filterKategori').value;const sort=document.getElementById('sortProduk').value;const grid=document.getElementById('productGrid');if(!grid)return;const cards=Array.from(grid.querySelectorAll('.product-card'));cards.forEach(c=>{const ok=(!q||(c.dataset.name+' '+c.dataset.code+' '+c.dataset.kategori).includes(q))&&(kat==='semua'||c.dataset.kategori===kat);c.style.display=ok?'flex':'none'});cards.sort((a,b)=>{if(sort==='harga_asc')return Number(a.dataset.harga)-Number(b.dataset.harga);if(sort==='harga_desc')return Number(b.dataset.harga)-Number(a.dataset.harga);if(sort==='stok_desc')return Number(b.dataset.stok)-Number(a.dataset.stok);return a.dataset.name.localeCompare(b.dataset.name)}).forEach(c=>grid.appendChild(c))}
function openGeneralChat(){document.getElementById('generalChatModal').classList.add('show'); if(!generalSession){generalSession=localStorage.getItem('po_general_session')||('GEN'+Date.now()+Math.random().toString(16).slice(2));localStorage.setItem('po_general_session',generalSession)} loadGeneralChat()}function closeGeneralChat(){document.getElementById('generalChatModal').classList.remove('show')}function fillGeneralChat(t){document.getElementById('generalChatText').value=t;document.getElementById('generalChatText').focus()}
async function loadGeneralChat(){try{const r=await fetch(`<?= po_esc(po_url('general_chat_ajax.php')) ?>?session=${encodeURIComponent(generalSession)}&entitas=${ENTITAS_ID}`);const d=await r.json();document.getElementById('generalChatRows').innerHTML=(d.rows||[]).map(x=>`<div class="bubble ${x.pengirim_tipe==='customer'?'customer':'admin'}"><b>${x.pengirim_tipe==='customer'?'Anda':'Admin'}</b><br>${esc(x.pesan).replace(/\n/g,'<br>')}<div class="time">${esc(x.tanggal)}</div></div>`).join('')||'<div class="empty">Belum ada chat. Kirim pertanyaan ke admin.</div>'}catch(e){}}
document.getElementById('generalChatForm').addEventListener('submit',async e=>{e.preventDefault();const pesan=document.getElementById('generalChatText').value.trim();if(!pesan)return;let nama=localStorage.getItem('po_general_name')||'';let hp=localStorage.getItem('po_general_phone')||'';if(!nama){nama=prompt('Nama Anda?')||'Pelanggan';localStorage.setItem('po_general_name',nama)}if(!hp){hp=prompt('No HP/WA Anda?')||'-';localStorage.setItem('po_general_phone',hp)}const fd=new FormData();fd.append('session',generalSession);fd.append('entitas',ENTITAS_ID);fd.append('nama',nama);fd.append('no_hp',hp);fd.append('pesan',pesan);const r=await fetch(`<?= po_esc(po_url('general_chat_ajax.php')) ?>`,{method:'POST',body:fd});const d=await r.json();if(!d.ok)return alert(d.message||'Gagal kirim chat');document.getElementById('generalChatText').value='';loadGeneralChat()});
renderCart();
</script>
</body></html>
